188	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
189	    @Override
190	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
191	        HttpHeaders headers = new HttpHeaders();
192	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
193	        String telephone = toE164(owner.getTelephone());
194	        if (telephone == null) {
195	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	        }
197	        if (!normalizeEmail(owner)) {
198	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
199	        }
200	        for (Owner existing : this.clinicService.findAllOwners()) {
201	            String existingTelephone = toE164(existing.getTelephone());
202	            if (telephone.equals(existingTelephone)) {
203	                return new ResponseEntity<>(HttpStatus.CONFLICT);
204	            }
205	        }
206	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()) && sharesHouseholdWithExisting(owner)) {
207	            return new ResponseEntity<>(HttpStatus.CONFLICT);
208	        }
209	        owner.setTelephone(telephone);
210	        if (owner.getRegistrationDate() == null) {
211	            owner.setRegistrationDate(java.time.LocalDate.now());
212	        }
213	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
214	        this.clinicService.saveOwner(owner);
215	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
216	        headers.setLocation(UriComponentsBuilder.newInstance()
217	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
218	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
224	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
225	        if (currentOwner == null) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        currentOwner.setAddress(ownerFieldsDto.getAddress());
229	        currentOwner.setCity(ownerFieldsDto.getCity());
230	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
231	        currentOwner.setLastName(ownerFieldsDto.getLastName());
232	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
233	        currentOwner.setEmail(ownerFieldsDto.getEmail());
234	        if (!normalizeEmail(currentOwner)) {
235	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
236	        }
237	        this.clinicService.saveOwner(currentOwner);
238	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Transactional
243	    @Override
244	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
245	        Owner owner = this.clinicService.findOwnerById(ownerId);
246	        if (owner == null) {
247	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	        }
249	        this.clinicService.deleteOwner(owner);
250	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
251	    }
