253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Override
255	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
256	        Owner owner = this.clinicService.findOwnerById(ownerId);
257	        if (owner == null) {
258	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
259	        }
260	        HttpHeaders headers = new HttpHeaders();
261	        Pet pet = petMapper.toPet(petFieldsDto);
262	        owner.setId(ownerId);
263	        pet.setOwner(owner);
264	        pet.getType().setName(null);
265	        this.clinicService.savePet(pet);
266	        PetDto petDto = petMapper.toPetDto(pet);
267	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
268	            .buildAndExpand(pet.getId()).toUri());
269	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
270	    }
271	
272	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
273	    @Override
274	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
275	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
276	        if (currentOwner != null) {
277	            Pet currentPet = this.clinicService.findPetById(petId);
278	            if (currentPet != null) {
279	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
280	                currentPet.setName(petFieldsDto.getName());
281	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
282	                this.clinicService.savePet(currentPet);
283	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
284	            }
285	        }
286	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
287	    }
