289	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
290	    @Override
291	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
292	        HttpHeaders headers = new HttpHeaders();
293	        Visit visit = visitMapper.toVisit(visitFieldsDto);
294	        Pet pet = new Pet();
295	        pet.setId(petId);
296	        visit.setPet(pet);
297	        this.clinicService.saveVisit(visit);
298	        VisitDto visitDto = visitMapper.toVisitDto(visit);
299	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
300	            .buildAndExpand(visit.getId()).toUri());
301	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
302	    }
