305	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
306	    @Override
307	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
308	        Owner owner = this.clinicService.findOwnerById(ownerId);
309	        if (owner != null) {
310	            Pet pet = owner.getPet(petId);
311	            if (pet != null) {
312	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
313	            }
314	        }
315	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
316	    }
